func onPrepare():
	var items = Game.PLAYER.INVENTORY.getItemsAndGems() + Game.OPPONENT.INVENTORY.getItemsAndGems()
	for character in [Game.PLAYER, Game.OPPONENT]:
		for stat in Character.Stat:
